function timed(onPause = () => {}) {
  let elapsed = 0;
  return {
    clock: { now: () => elapsed, pause: async (milliseconds) => {
      assert.equal(milliseconds, 5000);
      elapsed += milliseconds;
      await onPause(elapsed);
    } },
    elapsed: () => elapsed,
  };
}

