async () => {
  const repository = scratch();
  prepare(repository);
  let answer;
  const calls = await fsCallsUnder(admissionOf(stateIn(repository)), async () => { answer = await ran(verb, repository); });

  assert.equal(answer.code, 0, answer.text);
