async function awaiting(t, what, wait) {
  const named = () => t.diagnostic(`the test ended while it waited for ${what}`);
  t.signal.addEventListener('abort', named, { once: true });
  try {
    return await wait;
  } finally {
    t.signal.removeEventListener('abort', named);
  }
}

