    const failures = []; cleanupDeadline = performance.now() + 10_000;
    for (const fd of [writer, reader]) if (fd !== undefined) { try { closeSync(fd); } catch (error) { failures.push(error); } }
    writer = reader = undefined;
    if (cli) {
