  if (signal === 0 && pid === config.pid) {
    if (config.mode === 'eperm' && acknowledgements > 0 && !permissionFaultSent) {
      permissionFaultSent = true;
      record({ event: 'signal-zero', pid, controlled: true, error: 'EPERM' });
