      : `const child = ${api}(${api === 'fork' ? "'--version', []" : `${JSON.stringify(command)}, ['--version']`}, ${options}); const code = await new Promise((resolve, reject) => { child.on('error', reject); child.on('close', resolve); }); assert.equal(code, 0);`;
