  assert.deepEqual(built.made, [1]);
  assert.deepEqual(named(events, 'L3', 'dispatch'), []);
  assert.deepEqual(named(events, 'L1', 'dispatch.start'), []);
  assert.equal(built.makerCalls.length, 0, 'no started marker');
}

